<?php require __DIR__.'/common.php';
try {
 $id=positiveId($_GET['event']??'');
 $q=$pdo->prepare("SELECT e.*,v.venue_name,v.location,(SELECT MIN(price) FROM seats WHERE venue_id=e.venue_id AND status='available') starting_price FROM events e JOIN venues v ON v.venue_id=e.venue_id WHERE e.event_id=? AND e.status='active'");$q->execute([$id]);$event=$q->fetch();if(!$event)throw new RuntimeException('This event is not available.');
 $q=$pdo->prepare("SELECT * FROM event_sessions WHERE event_id=? AND session_status='active' AND CONCAT(session_date,' ',session_time)>NOW() ORDER BY session_date,session_time");$q->execute([$id]);$sessions=$q->fetchAll();
} catch(RuntimeException $e){showError($e instanceof PDOException?'Could not load this event.':$e->getMessage());}
pageStart($event['event_name']);bookingSteps(0); ?>
<p><a href="events.php">← Browse events</a></p><section class="panel event-detail"><img src="assets/<?=h($event['image'])?>" alt="<?=h($event['event_name'])?> event artwork"><div><p class="label"><?=h($event['category'])?></p><h1><?=h($event['event_name'])?></h1><p><?=h($event['venue_name'].' · '.$event['location'])?></p><p class="total">From <?=money($event['starting_price']??0)?></p>
<?php if($sessions): ?><form action="booking.php" method="get"><input type="hidden" name="event" value="<?=h($id)?>"><label for="event-session">Choose a session</label><select name="session" id="event-session"><?php foreach($sessions as $session): ?><option value="<?=h($session['session_id'])?>"><?=h($session['session_date'].' · '.substr($session['session_time'],0,5))?></option><?php endforeach; ?></select><p><button>Choose seats →</button></p></form><?php else: ?><p>No upcoming sessions. Please check back later.</p><?php endif; ?></div></section><section class="panel"><h2>About this event</h2><p><?=nl2br(h($event['description']))?></p><p>Choose VIP, Premium or Standard seats. Availability and prices are checked again when your booking is confirmed.</p></section><?php pageEnd(); ?>
